begin;
-- Add readable codes without changing existing UUID primary/foreign keys or business fields.
create function public.guard_record_number() returns trigger language plpgsql set search_path='' as $$begin
 if new.record_number is distinct from old.record_number then raise exception 'Record numbers cannot be changed';end if;return new;end$$;
revoke all on function public.guard_record_number() from public,anon,authenticated;
alter table public.estimate_snapshots add column record_number bigint generated always as identity;
alter table public.estimate_snapshots add column record_code text generated always as ('RG-EST-' || lpad(record_number::text,greatest(6,length(record_number::text)),'0')) stored;
alter table public.estimate_snapshots alter column record_code set not null;
alter table public.estimate_snapshots add constraint estimate_snapshots_record_code_key unique(record_code);
create trigger immutable_record_number before update on public.estimate_snapshots for each row execute function public.guard_record_number();
